import{_ as t}from"./chunks/policy-new-vulnerability.BuxOrLYz.js";import{_ as o}from"./chunks/policy-new-namespace.D3fhyQI-.js";import{_ as r,o as a,c as s,a3 as i}from"./chunks/framework.Ki30n65y.js";const n="/depgate/screenshots/policy-new.png",l="/depgate/screenshots/policy-new-license.png",k=JSON.parse('{"title":"Create a policy","description":"","frontmatter":{},"headers":[],"relativePath":"admin/create-policy.md","filePath":"admin/create-policy.md"}'),c={name:"admin/create-policy.md"};function d(h,e,p,m,g,u){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="create-a-policy" tabindex="-1">Create a policy <a class="header-anchor" href="#create-a-policy" aria-label="Permalink to &quot;Create a policy&quot;">​</a></h1><p>This guide walks through creating a policy in the web interface, then gives ready-made recipes for the policies most organizations start with. You need the <strong>Security</strong> role.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Decide three things:</p><ol><li><strong>What should be blocked</strong>, in one sentence. For example: &quot;versions with a critical vulnerability&quot;. That sentence picks the <a href="./policy-rules">rule</a>.</li><li><strong>Where it applies</strong>: every ecosystem or one, and every repository or some.</li><li><strong>Whether to monitor first.</strong> For a rule that covers a whole ecosystem, start in monitor mode and review the impact before you enforce. See <a href="./monitoring">Monitor before enforcing</a>.</li></ol><h2 id="step-by-step" tabindex="-1">Step by step <a class="header-anchor" href="#step-by-step" aria-label="Permalink to &quot;Step by step&quot;">​</a></h2><h3 id="_1-open-the-form" tabindex="-1">1. Open the form <a class="header-anchor" href="#_1-open-the-form" aria-label="Permalink to &quot;1. Open the form&quot;">​</a></h3><p>In the sidebar, choose <strong>Policies</strong>, then <strong>New policy</strong>. The form opens on its own page: the settings on the left and a <strong>Summary</strong> on the right that always shows, in plain words, what the policy will do.</p><p><img src="'+n+'" alt="An empty New policy form"></p><h3 id="_2-name-and-describe-it" tabindex="-1">2. Name and describe it <a class="header-anchor" href="#_2-name-and-describe-it" aria-label="Permalink to &quot;2. Name and describe it&quot;">​</a></h3><ul><li><strong>Name</strong>: short and specific, such as <code>Critical vulnerabilities</code> or <code>Approved licenses (PyPI)</code>. Developers see it in block messages.</li><li><strong>Description</strong> (optional): why the policy exists. Reviewers and auditors read it.</li></ul><h3 id="_3-set-priority-and-ecosystem" tabindex="-1">3. Set priority and ecosystem <a class="header-anchor" href="#_3-set-priority-and-ecosystem" aria-label="Permalink to &quot;3. Set priority and ecosystem&quot;">​</a></h3><ul><li><strong>Priority</strong>: lower numbers are evaluated first, and the first matching policy decides. Leave gaps (10, 20, 30) so you can insert policies later.</li><li><strong>Ecosystem</strong>: <strong>All</strong>, or a single ecosystem. Namespace protection always needs a single ecosystem.</li></ul><h3 id="_4-choose-where-it-applies" tabindex="-1">4. Choose where it applies <a class="header-anchor" href="#_4-choose-where-it-applies" aria-label="Permalink to &quot;4. Choose where it applies&quot;">​</a></h3><p>Under <strong>Applies to</strong>, keep <strong>All repositories</strong>, or choose <strong>Selected repositories</strong> and pick the repositories. See <a href="./policies#limit-a-policy-to-some-repositories">Limit a policy to some repositories</a>.</p><h3 id="_5-choose-the-rule" tabindex="-1">5. Choose the rule <a class="header-anchor" href="#_5-choose-the-rule" aria-label="Permalink to &quot;5. Choose the rule&quot;">​</a></h3><p>Choose one of the seven rule cards. The form then shows that rule&#39;s settings. To pick another rule, choose <strong>Change</strong>.</p><h3 id="_6-choose-the-action-and-enforcement" tabindex="-1">6. Choose the action and enforcement <a class="header-anchor" href="#_6-choose-the-action-and-enforcement" aria-label="Permalink to &quot;6. Choose the action and enforcement&quot;">​</a></h3><ul><li><strong>Action</strong> (Packages rule only): <strong>Block</strong> or <strong>Allow</strong>. Every other rule blocks.</li><li><strong>Enforcement</strong> (Block only): <strong>Enforce</strong> to block matching versions now, or <strong>Monitor only (log, don&#39;t block)</strong> to record what would be blocked. For broad rules the form recommends monitoring first.</li></ul><h3 id="_7-fill-in-the-rule" tabindex="-1">7. Fill in the rule <a class="header-anchor" href="#_7-fill-in-the-rule" aria-label="Permalink to &quot;7. Fill in the rule&quot;">​</a></h3><p>Enter the rule&#39;s settings. For example, for a Vulnerability rule, set <strong>CVSS score at least</strong> to <code>7.0</code>. Every option is described in <a href="./policy-rules">Policy rules</a>.</p><p><img src="'+t+'" alt="A Vulnerability policy that blocks CVSS 7.0 and higher, with the Summary panel"></p><h3 id="_8-check-the-summary-and-create" tabindex="-1">8. Check the summary and create <a class="header-anchor" href="#_8-check-the-summary-and-create" aria-label="Permalink to &quot;8. Check the summary and create&quot;">​</a></h3><p>Read the <strong>Summary</strong> panel. It states the action (&quot;Block versions with CVSS ≥ 7.0&quot;), how edge cases are handled (&quot;Vulnerabilities without CVSS: ignored&quot;), the ecosystem, the repositories, whether the policy is enabled, and its priority. If something is missing, a <strong>Next</strong> hint says what to fill in.</p><p>Choose <strong>Create policy</strong>. The policy takes effect within seconds on every DepGate replica.</p><div class="tip custom-block"><p class="custom-block-title">Test it</p><p>Open <a href="/depgate/developers/package-check">Package check</a> on a package you know, and confirm the policy blocks the versions you expect. A check never downloads or records anything.</p></div><h2 id="edit-a-policy" tabindex="-1">Edit a policy <a class="header-anchor" href="#edit-a-policy" aria-label="Permalink to &quot;Edit a policy&quot;">​</a></h2><p>Choose the pencil icon on the policy&#39;s row. The same form opens with the current settings. Choose <strong>Update policy</strong> to save. If you leave with unsaved changes, DepGate asks whether to discard them.</p><p>When you change the rule of a policy in monitor mode, DepGate rechecks everything it recorded against the new rule.</p><h2 id="recipes" tabindex="-1">Recipes <a class="header-anchor" href="#recipes" aria-label="Permalink to &quot;Recipes&quot;">​</a></h2><p>These policies cover the most common needs. Create them in monitor mode first where the table says so.</p><table tabindex="0"><thead><tr><th>Goal</th><th>Rule</th><th>Settings</th><th>Start in</th></tr></thead><tbody><tr><td>Block critical vulnerabilities</td><td>Vulnerability</td><td>CVSS score at least <code>9.0</code></td><td>Enforce</td></tr><tr><td>Block serious vulnerabilities that are likely to be exploited</td><td>Vulnerability</td><td>CVSS at least <code>7.0</code>, and Exploit likelihood (EPSS) at least <code>10 %</code></td><td>Monitor</td></tr><tr><td>Block a specific CVE</td><td>Vulnerability</td><td>CVE IDs: <code>CVE-2021-44228</code></td><td>Enforce</td></tr><tr><td>Only approved licenses</td><td>License</td><td>Block every license except: MIT, Apache-2.0, BSD-2-Clause, BSD-3-Clause, ISC</td><td>Monitor</td></tr><tr><td>Ban network copyleft</td><td>License</td><td>Block only: AGPL-3.0, SSPL-1.0, BUSL-1.1</td><td>Monitor</td></tr><tr><td>Cool-down for new releases</td><td>Release age</td><td>Published less than <code>72</code> hours ago</td><td>Monitor</td></tr><tr><td>Block unmaintained packages</td><td>Release age</td><td>No release in <code>730</code> days</td><td>Monitor</td></tr><tr><td>No pre-release builds</td><td>Release type</td><td>Pre-release, Dev release, Snapshot</td><td>Monitor</td></tr><tr><td>Block a bad version</td><td>Packages</td><td><code>lodash</code>, versions <code>0.0.0 - 4.17.20</code></td><td>Enforce</td></tr><tr><td>Always allow your own packages</td><td>Packages, <strong>Allow</strong></td><td><code>@acme/*</code> (priority lower than your Block policies)</td><td>Enforce</td></tr><tr><td>Stop dependency confusion</td><td>Namespace protection</td><td><code>@acme</code>, <code>acme-*</code> (ecosystem npm)</td><td>Monitor</td></tr><tr><td>Require healthy projects</td><td>Project health</td><td>Overall Scorecard at least <code>3</code></td><td>Monitor</td></tr></tbody></table><h3 id="example-approved-licenses-only" tabindex="-1">Example: Approved licenses only <a class="header-anchor" href="#example-approved-licenses-only" aria-label="Permalink to &quot;Example: Approved licenses only&quot;">​</a></h3><p><img src="'+l+'" alt="A License policy with an approved list"></p><ol><li><strong>Name</strong>: <code>Approved licenses (PyPI)</code>. <strong>Ecosystem</strong>: PyPI.</li><li><strong>Rule</strong>: License. <strong>Enforcement</strong>: Monitor only.</li><li>Choose <strong>Block every license except the approved ones</strong>.</li><li>Under <strong>Approved licenses</strong>, search for and add <code>MIT</code>, <code>Apache-2.0</code> and <code>BSD-3-Clause</code>.</li><li>Leave <strong>Allow packages with no license info</strong> off, so packages without a declared license are reviewed too.</li><li>Choose <strong>Create policy</strong>, then review the results on the Monitoring page after a few days of traffic.</li></ol><h3 id="example-protect-your-internal-names" tabindex="-1">Example: Protect your internal names <a class="header-anchor" href="#example-protect-your-internal-names" aria-label="Permalink to &quot;Example: Protect your internal names&quot;">​</a></h3><p><img src="'+o+'" alt="A Namespace protection policy for @acme"></p><ol><li><strong>Name</strong>: <code>Protect the @acme namespace</code>. <strong>Ecosystem</strong>: npm.</li><li><strong>Rule</strong>: Namespace protection.</li><li>Under <strong>Your package names</strong>, add <code>@acme</code> and <code>acme-*</code>.</li><li>Under <strong>Serve only from</strong>, keep your internal registries selected.</li><li>Use <strong>Test a name</strong> to confirm a name resolves where you expect.</li><li>Choose <strong>Create policy</strong>.</li></ol><p><a href="./namespace-protection">Namespace protection</a> explains the rollout in detail.</p>',39)])])}const w=r(c,[["render",d]]);export{k as __pageData,w as default};
